// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    MockERC20 token;
    EIP1271Signer maker;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        token = new MockERC20();
        maker = new EIP1271Signer();
    }

    function testFuzz_property(address to, uint256 nonce) public {
        vm.assume(to != address(0) && to != address(this) && to != address(c) && to != address(maker));

        PuttyV2.Order memory o;
        o.maker = address(maker);
        o.isCall = true;
        o.isLong = true;
        o.baseAsset = address(token);
        o.strike = 0;
        o.premium = 0;
        o.duration = 1;
        o.expiration = block.timestamp + 1;
        o.nonce = nonce;

        bytes memory emptySig = new bytes(0);
        uint256[] memory empty = new uint256[](0);

        c.fillOrder(o, emptySig, empty);

        uint256 takerId = uint256(c.hashOppositeOrder(o));

        // first transfer by the current owner (this test contract) to the fuzzed recipient
        c.transferFrom(address(this), to, takerId);

        // rule: the recipient now owns the position and can transfer it onward without approval
        bool ok;
        vm.prank(to);
        try c.transferFrom(to, address(this), takerId) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "recipient must be able to retransfer the received position");
    }
}

contract MockERC20 {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

contract EIP1271Signer {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}
